/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    public List<List<Integer>> zigzagLevelOrder(TreeNode root) {
        var result = new ArrayList<List<Integer>>();
        var lStack = new Stack<TreeNode>();
        var rStack = new Stack<TreeNode>();

        if (root != null) {
            lStack.push(root);
        }

        while (!lStack.empty() || !rStack.empty()) {
            var list = new ArrayList<Integer>();

            if (!lStack.empty()) {
                var size = lStack.size();
                for (var i = 0; i < size; i++) {
                    var cur = lStack.pop();
                    list.add(cur.val);

                    if (cur.left != null) {
                        rStack.push(cur.left);
                    }
                    if (cur.right != null) {
                        rStack.push(cur.right);
                    }
                }
            } else {
                var size = rStack.size();
                for (var i = 0; i < size; i++) {
                    var cur = rStack.pop();
                    list.add(cur.val);

                    if (cur.right != null) {
                        lStack.push(cur.right);
                    }
                    if (cur.left != null) {
                        lStack.push(cur.left);
                    }
                }
            }

            result.add(list);
        }

        return result;
    }
}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<vector<int>> zigzagLevelOrder(TreeNode* root) {

        vector<vector<int>> ans;

        if(root == NULL)
            return ans;

        queue<TreeNode*> q;
        bool seq = false;

        q.push(root);
        ans.push_back({root -> val});

        while(!q.empty()){

            int n = q.size();
            vector<int> level;

            while(n--){

                TreeNode* temp = q.front();
                q.pop();

                if(temp -> left){

                    level.push_back(temp -> left -> val);
                    q.push(temp -> left);

                }

                if(temp -> right){

                    level.push_back(temp -> right -> val);
                    q.push(temp -> right);

                }

            }

            if(level.size() and seq == true)
                ans.push_back(level);

            else if(level.size() and seq == false){
                reverse(level.begin(), level.end());
                ans.push_back(level);
            }

            seq = !seq;

        }

        return ans;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<vector<int>> zigzagLevelOrder(TreeNode* root) {
        if (root == nullptr) return {};  
        vector<vector<int>> ans;
        queue<TreeNode*> q;  
        q.push(root);
        int par = 0;
        while (!q.empty()) {
            int nodeCount = q.size();
            vector<int> v;
            while (nodeCount) {  
                TreeNode* node = q.front();  
                v.push_back(node-> val);  
                q.pop();  
                if (node -> left != nullptr) {
                    q.push(node -> left);  
                } 
                if (node -> right != nullptr) {
                    q.push(node -> right);  
                }
                nodeCount--;  
            }
            if (par++ % 2) {
                reverse(v.begin(), v.end());
            }
            ans.push_back(v); 
        }
        return ans;
    }
};

